const wa = DATA.settings.wa;
const waUrl = (name) => `https://wa.me/${wa}?text=${encodeURIComponent("Bonjour Ice Blue Lomé, je souhaite commander : " + name)}`;

function productCard(p) {
  return `<article class="card">
    <img src="${p.img}" alt="${escapeHtml(p.name)}" loading="lazy">
    <div class="card-body">
      <h3>${escapeHtml(p.name)}</h3>
      ${p.price ? `<div class="price">${escapeHtml(p.price)}</div>` : ''}
      ${p.desc ? `<div class="desc">${formatProductDesc(p.desc)}</div>` : ''}
      <div class="order"><a class="btn" href="${waUrl(p.name)}" target="_blank" rel="noopener">Commander</a></div>
    </div>
  </article>`;
}

function packCard(p) {
  return `<article class="card pack">
    <img src="${p.image}" alt="${escapeHtml(p.name)}" loading="lazy">
    <div class="card-body">
      <span class="tag">${escapeHtml(p.people || '')}</span>
      <h3>${escapeHtml(p.name)}</h3>
      <div class="desc">${escapeHtml(p.details || '')}</div>
      ${p.price ? `<div class="price">${escapeHtml(p.price)}</div>` : ''}
      ${p.waPrice ? `<div class="muted">${escapeHtml(p.waPrice)}</div>` : ''}
      <div class="order"><a class="btn" href="${waUrl(p.name)}" target="_blank" rel="noopener">Demander ce pack</a></div>
    </div>
  </article>`;
}

function escapeHtml(value) {
 return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function formatProductDesc(value) {
  let out = escapeHtml(value || "");

  const headings = [
    "Composition",
    "Composition",
    "Profil de saveur",
    "Idéal pour",
    "Texture",
    "Conseil Ice_Bluelome"
  ];

  headings.forEach(function(label) {
    out = out.split(label).join(
      '<strong class="product-heading-visible">' + label + '</strong>'
    );
  });

  out = out.split("Idéal pour").join('<strong class="product-heading-visible">Idéal pour</strong>');
  out = out.split("Texture").join('<strong class="product-heading-visible">Texture</strong>');
  return out.replace(/\n/g, "<br>");
}

document.getElementById('products').innerHTML = DATA.products.map(productCard).join('');
document.getElementById('packs-grid').innerHTML = DATA.packs.map(packCard).join('');

function ouvrirAvisPhoto(el){
  const img = el.querySelector("img");
  const modal = document.getElementById("reviewModal");
  const target = document.getElementById("reviewModalImg");
  if(!img || !modal || !target) return;
  target.src = img.src;
  target.alt = img.alt || "Avis client";
  modal.classList.add("open");
  modal.setAttribute("aria-hidden","false");
}
function fermerAvisPhoto(event){
  if(event){
    if(event.target && event.target.id !== "reviewModal" && event.target.tagName !== "BUTTON") return;
    event.stopPropagation();
  }
  const modal = document.getElementById("reviewModal");
  if(!modal) return;
  modal.classList.remove("open");
  modal.setAttribute("aria-hidden","true");
  const target = document.getElementById("reviewModalImg");
  if(target) target.src = "";
}
document.addEventListener("keydown", function(e){
  if(e.key === "Escape") fermerAvisPhoto({target:document.getElementById("reviewModal")});
});

const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxnsNbGbkzijkdsCIcFOrdB7wDHwALRRzXTLPd3UzRskUru2oRE7eeS0NnkHfZmYrbaGg/exec";

(function(){
  const form = document.getElementById("avisFormCentral");
  const list = document.getElementById("avisListeCentral");
  const status = document.getElementById("avisStatusCentral");

  function safe(v){
    return String(v ?? "").replace(/[&<>"']/g, c => ({
      "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"
    }[c]));
  }

  function renderAvis(avis){
    if(!Array.isArray(avis) || !avis.length){
      list.innerHTML = '<p class="muted">Soyez le premier à laisser un avis ⭐</p>';
      return;
    }
    list.innerHTML = avis.map(a => {
      const note = Math.max(1, Math.min(5, Number(a.rating) || 0));
      return `<article class="review-card-central">
        <div class="review-stars-central" aria-label="${note} sur 5">${"★".repeat(note)}${"☆".repeat(5-note)}</div>
        <div class="review-name-central">${safe(a.name)}</div>
        <div class="review-text-central">${safe(a.review)}</div>
      </article>`;
    }).join("");
  }

  function jsonp(params){
    return new Promise((resolve,reject)=>{
      const callbackName='iceBlueAvis_'+Date.now()+'_'+Math.floor(Math.random()*100000);
      const script=document.createElement('script');
      const q=new URLSearchParams({...params,callback:callbackName});
      const timer=setTimeout(()=>{cleanup();reject(new Error('timeout'));},15000);
      function cleanup(){clearTimeout(timer);delete window[callbackName];script.remove();}
      window[callbackName]=data=>{cleanup();resolve(data);};
      script.onerror=()=>{cleanup();reject(new Error('network'));};
      script.src=APPS_SCRIPT_URL+'?'+q.toString();
      document.head.appendChild(script);
    });
  }

  async function chargerAvis(){
    list.innerHTML='<p class="muted">Chargement des avis...</p>';
    try{
      const data=await jsonp({action:'list'});
      if(!data || data.ok!==true) throw new Error('server');
      renderAvis(data.reviews||[]);
    }catch(e){
      list.innerHTML='<p class="muted">Impossible de charger les avis pour le moment. Vérifiez le déploiement Google Apps Script.</p>';
    }
  }

  // Notation gauche -> droite : 1 clic = 1 étoile, 2 clics = 2 étoiles, etc.
  const starBox = document.querySelector('.stars-central');
  const starInputs = starBox ? [...starBox.querySelectorAll('input[name="note"]')] : [];
  const starLabels = starBox ? [...starBox.querySelectorAll('label')] : [];

  function updateStars(value){
    const n = Number(value) || 0;
    starLabels.forEach((label, i) => label.classList.toggle('active', i < n));
  }

  starInputs.forEach((input, index) => {
    input.addEventListener('change', () => updateStars(index + 1));
  });

  // Aperçu au survol, toujours de gauche à droite.
  starLabels.forEach((label, index) => {
    label.addEventListener('mouseenter', () => updateStars(index + 1));
  });
  if(starBox){
    starBox.addEventListener('mouseleave', () => {
      const selected = starInputs.findIndex(input => input.checked);
      updateStars(selected >= 0 ? selected + 1 : 0);
    });
  }

  if(form){
    form.addEventListener('submit',async function(e){
      e.preventDefault();
      const note=form.querySelector('input[name="note"]:checked');
      const nom=document.getElementById('avisNomCentral').value.trim();
      const texte=document.getElementById('avisTexteCentral').value.trim();
      const consent=document.getElementById('avisConsent').checked;
      const btn=form.querySelector('button');
      if(!note||nom.length<2||nom.length>60||texte.length<10||texte.length>500||!consent){status.textContent='Choisissez une note, un prénom, un avis de 10 à 500 caractères et acceptez la publication.';return;}
      btn.disabled=true; status.textContent='Enregistrement de votre avis...';
      try{
        const body=new URLSearchParams({action:'add',rating:note.value,name:nom,review:texte,consent:'yes',website:form.elements.website.value});
        await fetch(APPS_SCRIPT_URL,{method:'POST',mode:'no-cors',body});
        form.reset();
        updateStars(0);
        status.textContent='Merci ⭐ Votre avis a été transmis et sera affiché après validation.';
      }catch(e){
        status.textContent='Votre avis n’a pas pu être transmis. Réessayez plus tard.';
      }finally{btn.disabled=false;}
    });
  }

  chargerAvis();
})();

